namespace DevLab.Api.Infrastructure.Events;

/// <summary>Something that happened, in the past tense, owned by the module that raised it.</summary>
public interface IDomainEvent;

public interface IEventHandler<in TEvent> where TEvent : IDomainEvent
{
    Task HandleAsync(TEvent @event, CancellationToken ct);
}

public interface IEventBus
{
    Task PublishAsync<TEvent>(TEvent @event, CancellationToken ct) where TEvent : IDomainEvent;
}

/// <summary>
/// Modules never call each other's handlers: they publish an event and whoever is
/// interested subscribes. Same process, same transaction boundary is NOT guaranteed —
/// in production you'd persist the event first (outbox pattern) and dispatch it asynchronously.
/// </summary>
public sealed class InProcessEventBus(IServiceProvider services, ILogger<InProcessEventBus> logger) : IEventBus
{
    public async Task PublishAsync<TEvent>(TEvent @event, CancellationToken ct) where TEvent : IDomainEvent
    {
        // Resolved from the CURRENT scope → handlers can use scoped services (DbContext).
        var handlers = services.GetServices<IEventHandler<TEvent>>().ToList();
        logger.LogInformation("Event {Event} → {Count} handler(s)", typeof(TEvent).Name, handlers.Count);

        foreach (var handler in handlers)
            await handler.HandleAsync(@event, ct);
    }
}

backend/DevLab.Api/Infrastructure/Module.content:
namespace DevLab.Api.Infrastructure.Modules;

/// <summary>
/// A module = a bounded business area (Orders, Products…) that owns its data, its endpoints
/// and its services. Program.cs does not know the modules by name: it discovers them.
/// In a multi-project solution each module is its own assembly, referenced only through
/// its *.PublicApi project. Here they are folders in one assembly, and an architecture test
/// (ModuleBoundariesTests) enforces the same rule.
/// </summary>
public interface IModule
{
    void Register(IServiceCollection services, IConfiguration configuration);
}

/// <summary>One class per endpoint (a "slice"): found by assembly scanning, mapped automatically.</summary>
public interface IApiEndpoint
{
    void Map(IEndpointRouteBuilder app);
}

using System.Reflection;

namespace DevLab.Api.Infrastructure.Modules;

public static class ModuleExtensions
{
    /// <summary>Instantiates every IModule in the assembly and lets it register its services.</summary>
    public static IServiceCollection AddModules(this IServiceCollection services, IConfiguration configuration, Assembly assembly)
    {
        foreach (var module in Discover<IModule>(assembly))
            module.Register(services, configuration);
        return services;
    }

    /// <summary>Instantiates every IApiEndpoint and maps it. Adding a slice = adding a file, nothing else.</summary>
    public static IEndpointRouteBuilder MapApiEndpoints(this IEndpointRouteBuilder app, Assembly assembly)
    {
        foreach (var endpoint in Discover<IApiEndpoint>(assembly))
            endpoint.Map(app);
        return app;
    }

    private static IEnumerable<T> Discover<T>(Assembly assembly) =>
        assembly.GetTypes()
            .Where(t => typeof(T).IsAssignableFrom(t) && t is { IsAbstract: false, IsInterface: false })
            .Select(t => (T)Activator.CreateInstance(t)!);
}

backend/DevLab.Api/Infrastructure/Result.content:
namespace DevLab.Api.Infrastructure;

/// <summary>
/// Expected business failures are VALUES, not exceptions. An exception is for the unexpected
/// (bug, network down); "product not found" or "insufficient stock" are normal outcomes that
/// the caller must handle — the type system now forces it.
/// </summary>
public enum ErrorType { Validation, NotFound, Conflict, Forbidden }

public sealed record Error(string Code, string Description, ErrorType Type)
{
    public static Error NotFound(string code, string description) => new(code, description, ErrorType.NotFound);
    public static Error Conflict(string code, string description) => new(code, description, ErrorType.Conflict);
    public static Error Validation(string code, string description) => new(code, description, ErrorType.Validation);
    public static Error Forbidden(string code, string description) => new(code, description, ErrorType.Forbidden);
}

public readonly record struct Result<T>
{
    public T? Value { get; }
    public Error? Error { get; }
    public bool IsSuccess => Error is null;

    private Result(T? value, Error? error) { Value = value; Error = error; }

    public static Result<T> Success(T value) => new(value, null);
    public static Result<T> Failure(Error error) => new(default, error);

    // Implicit conversions keep handlers readable: `return order;` or `return OrderErrors.NotFound(id);`
    public static implicit operator Result<T>(T value) => Success(value);
    public static implicit operator Result<T>(Error error) => Failure(error);

    /// <summary>Railway-style: one place decides what happens in each branch.</summary>
    public TOut Match<TOut>(Func<T, TOut> onSuccess, Func<Error, TOut> onFailure) =>
        IsSuccess ? onSuccess(Value!) : onFailure(Error!);
}

public static class ResultExtensions
{
    /// <summary>Maps an Error to the right HTTP status + ProblemDetails. Endpoints never switch on ErrorType themselves.</summary>
    public static IResult ToProblem(this Error error) => Results.Problem(
        statusCode: error.Type switch
        {
            ErrorType.Validation => StatusCodes.Status400BadRequest,
            ErrorType.NotFound => StatusCodes.Status404NotFound,
            ErrorType.Conflict => StatusCodes.Status409Conflict,
            ErrorType.Forbidden => StatusCodes.Status403Forbidden,
            _ => StatusCodes.Status500InternalServerError,
        },
        title: error.Description,
        extensions: new Dictionary<string, object?> { ["code"] = error.Code });
}

